import Profile from './Profile';
import React from 'react';
import { connect } from 'react-redux';
import { getUserProfile, getUserStatus, updateUserStatus } from '../../redux/profile-reducer';

import { withAuthRedirect  } from '../../hoc/withAuthRedirect';
import { compose } from 'redux';


class ProfileContainer extends React.Component {



  componentDidMount() {

    let userId = this.props.userId;

    if (!userId) {
      userId = this.props.authorizedUserId
      if (!userId) {
        this.props.history.push('/login');
        return;
      }
    }
    this.getUserProfile(userId);

  }

  getUserProfile = (userId) => {
    this.props.getUserProfile(userId);
    this.props.getUserStatus(userId);
  };




  render() {


    return <Profile {...this.props} profile={this.props.profile} 
    status={this.props.status} 
    updateUserStatus={this.props.updateUserStatus}/>;

  }
}


// let mapSateToPropsForRedirect = (state) => ({
//   isAuth: state.auth.isAuth,
// })


// let AuthRedirectComponent = connect(mapSateToPropsForRedirect)(withAuthRedirect(ProfileContainer));


const mapStateToProps = (state) => ({
  profile: state.profilePage.profile,
  status: state.profilePage.status,
  isAuth: state.auth.isAuth,
  authorizedUserId: state.auth.userId

});


// compose(connect(mapStateToProps, { getUserProfile }),withAuthRedirect)(ProfileContainer);

export default compose(connect(mapStateToProps, { getUserProfile, getUserStatus, updateUserStatus }),withAuthRedirect)(ProfileContainer);

